from p"benchmark_harness.jo" import clock
kernel=(values:array<int64> count:int64):>int64=>{
let total:int64=0
loop i in [0..count) total+=values[values.length-1]
return total
}
main=():>void=>{
let values=[loop i in [0..100000) 0] values.push(1)
if kernel(values 1000) not=? 1000 panic("warmup")
let started=clock() let checksum=kernel(values 2000000) let elapsed=clock()-started
printl"{checksum} {elapsed}"
}

